"""Builds the test script run in Gemini's code execution sandbox, and reads
its results.

The model only writes test functions. This module assembles the script
(submitted code + tests + a small runner), so the code under test is exactly
what the user sent, and the same tests can be re-run on fixed code. The
results come from the script's own output, not from a model's summary.
"""

import json
import re

RESULTS_MARKER = "RESULTS_JSON:"
TEST_TIMEOUT_SECONDS = 5

_RUNNER = '''
# ---- test runner (generated by the code review assistant) ----
import json as _json
import signal as _signal
import traceback as _traceback

_SUBMISSION = {code}
_TESTS = {tests}


def expect_raises(exception, func, *args, **kwargs):
    """Passes if func(*args, **kwargs) raises exception."""
    try:
        func(*args, **kwargs)
    except exception:
        return
    raise AssertionError(f"expected {{exception.__name__}} to be raised")


def _timeout(signum, frame):
    raise TimeoutError("test took longer than {timeout} seconds")


_namespace = {{"__name__": "submission", "expect_raises": expect_raises}}
_report = {{"load_error": None, "tests": []}}
try:
    exec(compile(_SUBMISSION, "submission.py", "exec"), _namespace)
except BaseException as _e:
    _report["load_error"] = f"{{type(_e).__name__}}: {{_e}}"
else:
    try:
        exec(compile(_TESTS, "tests.py", "exec"), _namespace)
    except BaseException as _e:
        _report["load_error"] = f"the tests failed to load: {{type(_e).__name__}}: {{_e}}"
    for _name, _func in list(_namespace.items()):
        if not (_name.startswith("test_") and callable(_func)):
            continue
        _result = {{"name": _name, "status": "passed", "message": ""}}
        _signal.signal(_signal.SIGALRM, _timeout)
        _signal.alarm({timeout})
        try:
            _func()
        except AssertionError as _e:
            _result.update(status="failed", message=str(_e)[:300])
        except BaseException as _e:
            _frame = _traceback.extract_tb(_e.__traceback__)[-1]
            _result.update(
                status="error",
                message=f"{{type(_e).__name__}}: {{str(_e)[:200]}} "
                f"({{_frame.filename}} line {{_frame.lineno}})",
            )
        finally:
            _signal.alarm(0)
        _report["tests"].append(_result)
print("{marker}" + _json.dumps(_report))
'''


def source_literal(text: str) -> str:
    """A Python string literal for text that stays readable.

    Models copy plain source far more reliably than one long escaped line,
    so use a raw triple-quoted string when text allows it, else repr().
    """
    for quote in ('"""', "'''"):
        if quote not in text and not text.endswith(("\\", quote[0])):
            return f"r{quote}\n{text}\n{quote}[1:-1]"
    return repr(text)


def build_test_script(code: str, tests: str) -> str:
    """The full script: runs every test_* function against the code."""
    return _RUNNER.format(
        code=source_literal(code),
        tests=source_literal(tests),
        timeout=TEST_TIMEOUT_SECONDS,
        marker=RESULTS_MARKER,
    ).lstrip("\n")


def parse_results(output: str) -> dict | None:
    """Reads the runner's report from the execution output, with counts."""
    for line in reversed(output.splitlines()):
        if line.startswith(RESULTS_MARKER):
            try:
                report = json.loads(line[len(RESULTS_MARKER) :])
            except json.JSONDecodeError:
                return None
            tests = report.get("tests", [])
            counts = {
                s: sum(1 for t in tests if t["status"] == s)
                for s in ("passed", "failed", "error")
            }
            total = len(tests)
            return {
                **report,
                **counts,
                "total": total,
                "pass_rate": round(100 * counts["passed"] / total) if total else 0,
            }
    return None


def _normalize(code: str) -> str:
    return re.sub(r"\s+", "", code)


def same_code(executed: str, expected: str) -> bool:
    """True if the model executed the script it was given (whitespace aside)."""
    return _normalize(executed) == _normalize(expected)
